    // Kierunek prosto na widza – sam okrąg.
    ctx.beginPath(); ctx.arc(p[0], p[1], 7, 0, Math.PI * 2);
    ctx.fillStyle = t.pen ? t.color : 'transparent';
    ctx.fill(); ctx.stroke();
    ctx.restore();
