  ctx.moveTo(p[0] + dx * L * 0.65, p[1] + dy * L * 0.65);
  ctx.lineTo(bx + nx * W, by + ny * W);
  ctx.lineTo(p[0] - dx * L * 0.2, p[1] - dy * L * 0.2);
  ctx.lineTo(bx - nx * W, by - ny * W);
  ctx.closePath();
  ctx.fillStyle = t.pen ? t.color : pal.bg;
  ctx.globalAlpha = 0.92;
  ctx.fill();
  ctx.globalAlpha = 1;
  ctx.stroke();
  ctx.setLineDash([]);
  ctx.beginPath(); ctx.arc(p[0], p[1], 2.2, 0, Math.PI * 2);
