import { expect } from 'bun:test';
import { run } from '../src/lang/index';

export type Mode = '2d' | '3d';
export type Vec = [number, number, number];
export interface Seg {
  from: Vec;
  to: Vec;
  color: string;
  width: number;
}

export function exec(src: string, mode: Mode = '2d') {
  return run(src, mode) as unknown as {
    segments: Seg[];
    error: null | { message: string; line: number; column: number };
  };
}

/** Runs the program, asserts no error, returns segments. */
export function ok(src: string, mode: Mode = '2d'): Seg[] {
  const r = exec(src, mode);
  if (r.error !== null) {
    throw new Error(`unexpected error ${JSON.stringify(r.error)} for program:\n${src.slice(0, 300)}`);
  }
  return r.segments;
}

/** Runs the program, asserts an error with a non-empty message. */
export function fails(src: string, mode: Mode = '2d') {
  const r = exec(src, mode);
  expect(r.error).not.toBeNull();
  expect(typeof r.error!.message).toBe('string');
  expect(r.error!.message.length).toBeGreaterThan(0);
  return r;
}

/** Asserts error at line/column. */
export function failsAt(src: string, line: number, column: number, mode: Mode = '2d') {
  const r = fails(src, mode);
  expect({ line: r.error!.line, column: r.error!.column }).toEqual({ line, column });
  return r;
}

/** Asserts a parse-time error at line/column (nothing drawn). */
export function parseFailsAt(src: string, line: number, column: number, mode: Mode = '2d') {
  const r = failsAt(src, line, column, mode);
  expect(r.segments).toEqual([]);
  return r;
}

/** Asserts a parse-time error (nothing drawn), position not checked. */
export function parseFails(src: string, mode: Mode = '2d') {
  const r = fails(src, mode);
  expect(r.segments).toEqual([]);
  return r;
}

/** 1-based line/column of the n-th (1-based) occurrence of needle in src. */
export function at(src: string, needle: string, occurrence = 1): { line: number; column: number } {
  let idx = -1;
  for (let i = 0; i < occurrence; i++) {
    idx = src.indexOf(needle, idx + 1);
    if (idx < 0) throw new Error(`needle ${needle} not found`);
  }
  const before = src.slice(0, idx);
  const line = before.split('\n').length;
  const column = idx - before.lastIndexOf('\n');
  return { line, column };
}

export function failsAtNeedle(src: string, needle: string, occurrence = 1, mode: Mode = '2d') {
  const p = at(src, needle, occurrence);
  return failsAt(src, p.line, p.column, mode);
}

export function closeVec(actual: number[], expected: number[], digits = 6) {
  expect(actual.length).toBe(3);
  for (let i = 0; i < 3; i++) expect(actual[i]).toBeCloseTo(expected[i], digits);
}

export function closeSeg(s: Seg, from: number[], to: number[]) {
  closeVec(s.from, from);
  closeVec(s.to, to);
}

/** Signed Y-extent of each segment (for programs that only move along Y). */
export function dy(segs: Seg[]): number[] {
  return segs.map((s) => +(s.to[1] - s.from[1]).toFixed(9));
}

/** End point of the last segment. */
export function last(segs: Seg[]): Vec {
  expect(segs.length).toBeGreaterThan(0);
  return segs[segs.length - 1].to;
}

import { describe, expect, test } from 'bun:test';
import { ok, fails, parseFails, parseFailsAt, dy, closeSeg } from './helpers';

describe('case-insensitivity', () => {
  test('keywords ignore case', () => {
    expect(dy(ok('NP 10 Np 5 nP 2 FORWARD 1 Fd 1'))).toEqual([10, 5, 2, 1, 1]);
  });
  test('accented keywords ignore case', () => {
    expect(dy(ok('NAPRZÓD 10 Naprzód 2'))).toEqual([10, 2]);
    expect(dy(ok('POWTÓRZ 2 [NP 1]'))).toEqual([1, 1]);
  });
  test('variable names ignore case', () => {
    expect(dy(ok('NIECH Abc 4 np aBC np :ABC'))).toEqual([4, 4]);
  });
  test('procedure names, parameter names and header keywords ignore case', () => {
    const src = 'OTO Kwadrat MA: Bok\nNP bok\nNP :BOK\nJUŻ\nkwadrat 7\nKWADRAT 3';
    expect(dy(ok(src))).toEqual([7, 7, 3, 3]);
  });
  test('nrpowt ignores case', () => {
    expect(dy(ok('powtorz 2 [np NRPOWT np RepCount]'))).toEqual([1, 1, 2, 2]);
  });
});

describe('whitespace and newlines', () => {
  test('newline between command and argument is fine', () => {
    expect(dy(ok('np\n10'))).toEqual([10]);
  });
  test('tabs and multiple spaces separate tokens', () => {
    expect(dy(ok('np\t10   \t np  3'))).toEqual([10, 3]);
  });
  test('repeat may span lines', () => {
    expect(dy(ok('powtorz 2\n[\n  np 1\n]\n'))).toEqual([1, 1]);
  });
  test('brackets need no surrounding whitespace', () => {
    expect(dy(ok('powtorz 2[np 1]'))).toEqual([1, 1]);
  });
  test('empty program is fine', () => {
    expect(ok('')).toEqual([]);
    expect(ok('   \n\n  ')).toEqual([]);
  });
});

describe('comments', () => {
  test('semicolon comment runs to end of line', () => {
    expect(dy(ok('np 10 ; np 20\nnp 5'))).toEqual([10, 5]);
  });
  test('comment-only program', () => {
    expect(ok('; tylko komentarz')).toEqual([]);
  });
  test('comment directly after a token', () => {
    expect(dy(ok('np 10;komentarz\nnp 2'))).toEqual([10, 2]);
  });
  test('brackets and junk in a comment are ignored', () => {
    expect(dy(ok('np 1 ; ] [ ( foo 1e3 "#zz"\nnp 2'))).toEqual([1, 2]);
  });
  test('comment at end of program without newline', () => {
    expect(dy(ok('np 3 ; koniec'))).toEqual([3]);
  });
  test('error positions after a comment line', () => {
    parseFailsAt('; komentarz\n   foo', 2, 4);
  });
});

describe('numbers', () => {
  test('integer, decimal, and leading-dot literals', () => {
    expect(dy(ok('np 80'))).toEqual([80]);
    expect(dy(ok('np 12.5'))).toEqual([12.5]);
    expect(dy(ok('np .5'))).toEqual([0.5]);
    expect(dy(ok('np 0.25'))).toEqual([0.25]);
  });
  test('sign is an operator, not part of the literal', () => {
    expect(dy(ok('np -5'))).toEqual([-5]);
    expect(dy(ok('np +5'))).toEqual([5]);
  });
  for (const bad of ['1e3', '1E3', '0x10', 'NaN', 'Infinity', 'nan', 'infinity']) {
    test(`${bad} is not a number (parse-time error)`, () => {
      const r = parseFails(`np 10\nnp ${bad}`);
      expect(r.error!.line).toBe(2);
      expect([4, 5]).toContain(r.error!.column);
    });
  }
  test('NaN and Infinity are rejected at their position', () => {
    parseFailsAt('np NaN', 1, 4);
    parseFailsAt('np Infinity', 1, 4);
  });
});

describe('colour literals', () => {
  test('lowercase hex', () => {
    const s = ok('kolor "#abcdef" np 1');
    expect(s[0].color).toBe('#abcdef');
  });
  test('uppercase / mixed hex is accepted and reported lowercase', () => {
    expect(ok('kolor "#ABCDEF" np 1')[0].color).toBe('#abcdef');
    expect(ok('kolor "#16866A" np 1')[0].color).toBe('#16866a');
    expect(ok('kolor "#aB12Cd" np 1')[0].color).toBe('#ab12cd');
  });
  for (const bad of ['"#12345"', '"#1234567"', '"#12345g"', '"123456"', '#123456', '5', '"#123456', '"#"', '""', 'abc']) {
    test(`malformed colour ${bad} is a parse-time error at the argument`, () => {
      parseFailsAt(`np 1 kolor ${bad}`, 1, 12);
    });
  }
  test('colour literal is not an expression', () => {
    parseFailsAt('np "#123456"', 1, 4);
  });
});

describe('operators and parentheses', () => {
  test('parentheses group', () => {
    expect(dy(ok('np (2 + 3) * 2'))).toEqual([10]);
  });
  test('all six comparisons are recognised', () => {
    const segs = ok(
      'jeśli 1 < 2 [np 1] jeśli 2 > 1 [np 2] jeśli 1 = 1 [np 3] jeśli 1 <= 1 [np 4] jeśli 1 >= 1 [np 5] jeśli 1 <> 2 [np 6]',
    );
    expect(dy(segs)).toEqual([1, 2, 3, 4, 5, 6]);
  });
  test('unknown characters are errors', () => {
    fails('np 1 & 2');
    fails('np 1 % 2');
  });
});

describe('basic segment shape', () => {
  test('forward from origin', () => {
    const s = ok('np 10');
    expect(s.length).toBe(1);
    closeSeg(s[0], [0, 0, 0], [0, 10, 0]);
  });
});

import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';
import { LineSegments2 } from 'three/examples/jsm/lines/LineSegments2.js';
import { LineSegmentsGeometry } from 'three/examples/jsm/lines/LineSegmentsGeometry.js';
import { LineMaterial } from 'three/examples/jsm/lines/LineMaterial.js';
import type { Segment, TurtleState } from '../lang';
import type { Vec3 } from '../lang/geometry';
import { h, nextPaint } from './dom';
import { EMPTY_FRAME, gridStep, readPalette, type Palette, type SceneFrame } from './paint';
import type { StageView } from './view2d';

const DEFAULT_DIR = new THREE.Vector3(0.48, -0.78, 0.55).normalize();

export class View3D implements StageView {
  readonly element: HTMLElement;
  private readonly renderer: THREE.WebGLRenderer;
  private readonly scene = new THREE.Scene();
  private readonly camera: THREE.PerspectiveCamera;
  private readonly controls: OrbitControls;
  private readonly drawing = new THREE.Group();
  private readonly partialGroup = new THREE.Group();
  private readonly ghostGroup = new THREE.Group();
  private readonly helpers = new THREE.Group();
  private readonly turtle: THREE.Group;
  private turtleBody!: THREE.Mesh;
  private turtleState: TurtleState | null = null;
  private frame: SceneFrame = EMPTY_FRAME;
  private builtSegments: readonly Segment[] | null = null;
  private builtCount = -1;
  private builtGhost: readonly Segment[] | null = null;
  private materials = new Set<LineMaterial>();
  private palette: Palette;
  private autoFit = true;
  private pending = false;
  private visible = true;
  private gridSize = 0;
  private width = 300;
  private height = 300;

  constructor(label: string, private readonly onLost: () => void) {
    this.renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false });
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    const canvas = this.renderer.domElement;
    canvas.classList.add('stage-canvas');
    canvas.tabIndex = 0;
    canvas.setAttribute('role', 'img');
    canvas.setAttribute('aria-label', label);
    canvas.setAttribute('aria-roledescription', 'rysunek przestrzenny');
    canvas.addEventListener('webglcontextlost', (e) => {
      e.preventDefault();
      this.onLost();
    });
    this.element = h('div', { class: 'stage-view stage-3d' }, canvas);

    this.camera = new THREE.PerspectiveCamera(40, 1, 0.5, 20000);
    this.camera.up.set(0, 0, 1);
    this.camera.position.copy(DEFAULT_DIR).multiplyScalar(520);
    this.controls = new OrbitControls(this.camera, canvas);
    this.controls.target.set(0, 40, 30);
    this.controls.screenSpacePanning = true;
    this.controls.zoomToCursor = true;
    this.controls.addEventListener('change', () => this.schedule());
    this.controls.addEventListener('start', () => canvas.focus({ preventScroll: true }));
    canvas.addEventListener('wheel', () => { this.autoFit = false; }, { passive: true });
