import { describe, expect, test } from 'bun:test';
import { ok, fails, failsAt, parseFailsAt, dy } from './helpers';

const len = (src: string) => dy(ok(src));

describe('precedence and associativity', () => {
  test('spec examples', () => {
    expect(len('np 20 - 5 - 3')).toEqual([12]);
    expect(len('np 2 + 3 * 4')).toEqual([14]);
  });
  test('more cases', () => {
    expect(len('np 100 / 10 / 2')).toEqual([5]);
    expect(len('np 8 / 2 * 2')).toEqual([8]);
    expect(len('np 2 * 3 + 4')).toEqual([10]);
    expect(len('np 10 - 2 * 3')).toEqual([4]);
    expect(len('np (2 + 3) * 4')).toEqual([20]);
    expect(len('np 2 * (3 + 4)')).toEqual([14]);
    expect(len('np ((1 + 1) * (2 + 2))')).toEqual([8]);
    expect(len('np 1 - 2 + 3')).toEqual([2]);
    expect(len('np 24 / 4 / 3 * 2')).toEqual([4]);
  });
  test('intermediate values may exceed coordinate range', () => {
    expect(len('np 200000 - 150000')).toEqual([50000]);
  });
});

describe('binary-operator whitespace rule', () => {
  test('both sides or neither', () => {
    expect(len('np 10 - 5')).toEqual([5]);
    expect(len('np 10-5')).toEqual([5]);
    expect(len('np 1+2')).toEqual([3]);
    expect(len('np 2*3')).toEqual([6]);
    expect(len('np 6/2')).toEqual([3]);
    expect(len('np 1 + 2')).toEqual([3]);
    expect(len('np 2 * 3')).toEqual([6]);
    expect(len('np 6 / 2')).toEqual([3]);
  });
  test('np 10 -5 is an error at the -, nothing drawn', () => {
    parseFailsAt('np 10 -5', 1, 7);
    parseFailsAt('np 1\nnp 10 -5', 2, 7);
  });
  for (const op of ['+', '*', '/'])
    test(`whitespace only on the left of ${op} is an error at the operator`, () => {
      parseFailsAt(`np 10 ${op}5`, 1, 7);
    });
  for (const op of ['-', '+', '*', '/'])
    test(`whitespace only on the right of ${op} is an error at the operator`, () => {
      parseFailsAt(`np 10${op} 5`, 1, 6);
    });
  test('stray -5 inside parentheses', () => {
    parseFailsAt('np (10 -5)', 1, 8);
  });
  test('stray -(5)', () => {
    parseFailsAt('np 10 -(5)', 1, 7);
  });
  test('rule does not apply to comparisons', () => {
    expect(len('jeśli 1 <2 [np 1]')).toEqual([1]);
    expect(len('jeśli 1< 2 [np 1]')).toEqual([1]);
    expect(len('jeśli 1<2 [np 1]')).toEqual([1]);
    expect(len('jeśli 2 >=2 [np 1]')).toEqual([1]);
    expect(len('jeśli 2<> 3 [np 1]')).toEqual([1]);
    expect(len('jeśli 2= 2 [np 1]')).toEqual([1]);
  });
  test('rule applies inside conditions', () => {
    parseFailsAt('jeśli 1 -1 = 0 [np 1]', 1, 9);
  });
});

describe('unary signs', () => {
  test('spec examples', () => {
    expect(len('np -(3 - 5)')).toEqual([2]);
    expect(len('np - -2')).toEqual([2]);
    expect(len('niech bok 4 np -bok')).toEqual([-4]);
  });
  test('unary after binary operators', () => {
    expect(len('np 2 * -3')).toEqual([-6]);
    expect(len('np 3 - -2')).toEqual([5]);
    expect(len('np 3 + -2')).toEqual([1]);
    expect(len('np 6 / -2')).toEqual([-3]);
    expect(len('np 2*-3')).toEqual([-6]);
  });
  test('stacked and mixed', () => {
    expect(len('np - - -2')).toEqual([-2]);
    expect(len('np +-2')).toEqual([-2]);
    expect(len('np -+2')).toEqual([-2]);
    expect(len('np + + 2')).toEqual([2]);
    expect(len('np - 5')).toEqual([-5]);
  });
  test('unary binds to operand, tighter than *', () => {
    expect(len('np -2 * 3')).toEqual([-6]);
    expect(len('np -2 + 5')).toEqual([3]);
  });
  test('unary on nrpowt and legacy names', () => {
    expect(len('powtorz 2 [np -nrpowt]')).toEqual([-1, -2]);
    expect(len('niech a 3 np -:a')).toEqual([-3]);
  });
});

describe('names in expressions', () => {
  test('variable and legacy :name', () => {
    expect(len('niech x 5 np x np :x np x * x')).toEqual([5, 5, 25]);
  });
});

describe('division by zero and non-finite values', () => {
  test('division by zero is a run-time error at the argument', () => {
    const r = failsAt('np 10\nnp 5 / 0', 2, 4);
    expect(dy(r.segments)).toEqual([10]);
  });
  test('reported at first token of the argument expression', () => {
    const r = failsAt('np 10 np 2 + 5 / (3 - 3)', 1, 10);
    expect(r.segments.length).toBe(1);
  });
  test('reported at a leading unary sign', () => {
    const r = failsAt('np 1 np -(1 / 0)', 1, 9);
    expect(r.segments.length).toBe(1);
  });
  test('division by zero in a turn', () => {
    const r = failsAt('np 1 pw 1 / 0', 1, 9);
    expect(r.segments.length).toBe(1);
  });
  test('not raised when the code is not executed', () => {
    expect(len('jeśli 1 = 2 [np 1 / 0] np 1')).toEqual([1]);
  });
  test('non-finite result is a run-time error at the argument', () => {
    const big = '9'.repeat(200);
    const r = failsAt(`np 1\nnp ${big} * ${big}`, 2, 4);
    expect(r.segments.length).toBe(1);
  });
  test('0 / 0 is a run-time error', () => {
    const r = failsAt('np 3 np 0 / 0', 1, 9);
    expect(r.segments.length).toBe(1);
  });
});

describe('comparisons', () => {
  const cases: [string, boolean][] = [
    ['1 < 2', true], ['2 < 1', false], ['1 < 1', false],
    ['2 > 1', true], ['1 > 2', false], ['1 > 1', false],
    ['1 = 1', true], ['1 = 2', false],
    ['1 <= 1', true], ['1 <= 2', true], ['2 <= 1', false],
    ['1 >= 1', true], ['2 >= 1', true], ['1 >= 2', false],
    ['1 <> 2', true], ['1 <> 1', false],
    ['2 + 3 = 5', true], ['2 * 3 > 5 + 0.5', true], ['-3 = 0 - 3', true],
    ['3 = -3', false],
  ];
  for (const [cond, holds] of cases)
    test(`${cond} is ${holds}`, () => {
      expect(ok(`jeśli ${cond} [np 1]`).length).toBe(holds ? 1 : 0);
    });
  test('comparisons are exact', () => {
    expect(ok('jeśli 0.1 + 0.2 = 0.3 [np 1]')).toEqual([]);
    expect(ok('jeśli 0.1 + 0.2 <> 0.3 [np 1]').length).toBe(1);
    expect(ok('jeśli 0.5 + 0.25 = 0.75 [np 1]').length).toBe(1);
  });
  test('comparison outside a condition is an error', () => {
    fails('np 1 < 2');
  });
  test('condition without comparison is an error', () => {
    parseFailsAt('np 1\njeśli 1 [np 1]', 2, 9);
  });
});

describe('expression errors', () => {
  test('missing operand at )', () => {
    parseFailsAt('np (2 * )', 1, 9);
    parseFailsAt('np ()', 1, 5);
  });
  test('missing argument before a command reported at that command', () => {
    parseFailsAt('np pw 90', 1, 4);
  });
  test('missing argument at end of program reported at command', () => {
    parseFailsAt('np 10\npw', 2, 1);
  });
  test('missing operand after operator at end', () => {
    fails('np 2 +');
  });
  test('unbalanced parenthesis', () => {
    parseFailsAt('np 1 np (1 + 2', 1, 0 + 'np 1 np '.length + 1).segments;
  });
  test('stray closing parenthesis', () => {
    parseFailsAt('np 1 + 2)', 1, 9);
  });
});

import { describe, expect, test } from 'bun:test';
import { ok, closeSeg, closeVec, last } from './helpers';

const S3 = Math.sqrt(3) / 2; // sin 60 = cos 30
const R2 = Math.SQRT1_2;

describe('2D turning', () => {
  test('square returns to the origin', () => {
    const s = ok('powtorz 4 [np 10 pw 90]');
    expect(s.length).toBe(4);
    closeSeg(s[0], [0, 0, 0], [0, 10, 0]);
    closeSeg(s[1], [0, 10, 0], [10, 10, 0]);
    closeSeg(s[2], [10, 10, 0], [10, 0, 0]);
    closeSeg(s[3], [10, 0, 0], [0, 0, 0]);
  });
  test('right 30 / left 30', () => {
    closeVec(last(ok('pw 30 np 10')), [5, 10 * S3, 0]);
    closeVec(last(ok('lw 30 np 10')), [-5, 10 * S3, 0]);
  });
  test('negative angles turn the other way', () => {
    closeVec(last(ok('pw -90 np 10')), [-10, 0, 0]);
    closeVec(last(ok('lw -90 np 10')), [10, 0, 0]);
  });
  test('angles beyond 360 and decimals', () => {
    closeVec(last(ok('pw 450 np 10')), [10, 0, 0]);
    closeVec(last(ok('pw 22.5 pw 22.5 np 10')), [10 * R2, 10 * R2, 0]);
  });
  test('ws after turn', () => {
    closeVec(last(ok('pw 90 ws 10')), [-10, 0, 0]);
  });
  test('all 2D coordinates have z = 0', () => {
    for (const s of ok('powtorz 7 [np 13 pw 51.4]')) {
      expect(s.from[2]).toBeCloseTo(0, 9);
      expect(s.to[2]).toBeCloseTo(0, 9);
    }
  });
});

describe('3D pitch', () => {
  test('gora 90 heads along former up (+Z)', () => {
    closeVec(last(ok('gora 90 np 10', '3d')), [0, 0, 10]);
  });
  test('dol 90 heads -Z', () => {
    closeVec(last(ok('dol 90 np 10', '3d')), [0, 0, -10]);
  });
  test('gora 30 / dol 30', () => {
    closeVec(last(ok('gora 30 np 10', '3d')), [0, 10 * S3, 5]);
    closeVec(last(ok('dol 30 np 10', '3d')), [0, 10 * S3, -5]);
  });
  test('negative pitch goes the other way', () => {
    closeVec(last(ok('gora -90 np 10', '3d')), [0, 0, -10]);
  });
  test('up vector follows: second gora 90 heads -Y', () => {
    closeVec(last(ok('gora 90 gora 90 np 10', '3d')), [0, -10, 0]);
  });
  test('pitch keeps the right vector', () => {
    closeVec(last(ok('gora 37 pw 90 np 10', '3d')), [10, 0, 0]);
    closeVec(last(ok('gora 90 lw 90 np 10', '3d')), [-10, 0, 0]);
  });
  test('turning keeps up vector', () => {
    closeVec(last(ok('pw 37 gora 90 np 10', '3d')), [0, 0, 10]);
  });
  test('turn, pitch, turn', () => {
    // pw 90: H=+X R=-Y U=+Z ; gora 90: H=+Z U=-X R=-Y ; pw 90: H=-Y
    const s = ok('pw 90 gora 90 np 10 pw 90 np 10', '3d');
    expect(s.length).toBe(2);
    closeSeg(s[0], [0, 0, 0], [0, 0, 10]);
    closeSeg(s[1], [0, 0, 10], [0, -10, 10]);
  });
  test('turn after pitch rotates around the new up', () => {
    // gora 90: H=+Z, U=-Y, R=+X ; pw 90: H=+X
    const s = ok('gora 90 np 10 pw 90 np 10', '3d');
    closeSeg(s[1], [0, 0, 10], [10, 0, 10]);
  });
});

describe('3D roll', () => {
  test('roll does not change heading', () => {
    closeVec(last(ok('pp 37 np 10', '3d')), [0, 10, 0]);
    closeVec(last(ok('pl 37 np 10', '3d')), [0, 10, 0]);
  });
  test('after pp 90 right is former down (-Z)', () => {
    closeVec(last(ok('pp 90 pw 90 np 10', '3d')), [0, 0, -10]);
  });
  test('after pp 90 up is former right (+X)', () => {
    closeVec(last(ok('pp 90 gora 90 np 10', '3d')), [10, 0, 0]);
  });
  test('after pl 90 up is former left (-X), right is former up (+Z)', () => {
    closeVec(last(ok('pl 90 gora 90 np 10', '3d')), [-10, 0, 0]);
    closeVec(last(ok('pl 90 pw 90 np 10', '3d')), [0, 0, 10]);
  });
  test('negative roll goes the other way', () => {
    closeVec(last(ok('pp -90 pw 90 np 10', '3d')), [0, 0, 10]);
  });
  test('pp 30 then pitch up 90', () => {
    closeVec(last(ok('pp 30 gora 90 np 10', '3d')), [5, 0, 10 * S3]);
    closeVec(last(ok('pl 30 gora 90 np 10', '3d')), [-5, 0, 10 * S3]);
  });
  test('upside down turtle: pp 180 then right turns towards -X', () => {
    closeVec(last(ok('pp 180 pw 90 np 10', '3d')), [-10, 0, 0]);
  });
  test('pp 90 then dol 90 heads -X', () => {
    closeVec(last(ok('pp 90 dol 90 np 10', '3d')), [-10, 0, 0]);
  });
  test('roll, pitch, turn', () => {
    // pp 90: U=+X R=-Z ; gora 90: H=+X U=-Y R=-Z ; pw 90: H=-Z
    const s = ok('pp 90 gora 90 np 10 pw 90 np 10', '3d');
    closeSeg(s[0], [0, 0, 0], [10, 0, 0]);
    closeSeg(s[1], [10, 0, 0], [10, 0, -10]);
  });
  test('roll after turning rolls around current heading', () => {
    // pw 90: H=+X R=-Y U=+Z ; pp 90: U=-Y R=-Z ; gora 90: H=-Y
    closeVec(last(ok('pw 90 pp 90 gora 90 np 10', '3d')), [0, -10, 0]);
  });
});

describe('2D and 3D agree on flat programs', () => {
  test('identical coordinates', () => {
    const src =
      'powtorz 5 [np 20 pw 144] lw 33.3 ws 7 pod np 3 opu kolor "#123abc" grubosc 4 powtorz 3 [np nrpowt * 5 lw 120] dom np 2';
    const a = ok(src, '2d');
    const b = ok(src, '3d');
    expect(a.length).toBe(b.length);
    expect(a.length).toBeGreaterThan(0);
    for (let i = 0; i < a.length; i++) {
