import { describe, expect, test } from 'bun:test';
import { ok, fails, failsAt, parseFails, parseFailsAt, dy } from './helpers';

const len = (src: string) => dy(ok(src));

describe('repeat', () => {
  test('basic', () => {
    expect(len('powtorz 3 [np 1]')).toEqual([1, 1, 1]);
  });
  test('zero runs nothing', () => {
    expect(ok('powtorz 0 [np 1]')).toEqual([]);
  });
  test('empty body', () => {
    expect(ok('powtorz 5 []')).toEqual([]);
  });
  test('count from expressions', () => {
    expect(len('powtorz 9 / 3 [np 1]').length).toBe(3);
    expect(len('powtorz 1 + 1 [np 1]').length).toBe(2);
    expect(len('powtorz 4.0 [np 1]').length).toBe(4);
  });
  test('nested repeats', () => {
    expect(ok('powtorz 3 [powtorz 4 [np 1]]').length).toBe(12);
  });
  for (const bad of ['10001', '-1', '2.5', '20000 / 2 + 1', '7 / 2', '- 1'])
    test(`literal count ${bad} is a parse-time error at the argument`, () => {
      parseFailsAt(`np 1 powtorz ${bad} [np 1]`, 1, 14);
    });
  test('literal count 10000 passes parsing (fails later only on the op limit)', () => {
    const r = fails('np 1 powtorz 10000 []');
    expect(r.segments.length).toBe(1);
  });
  test('count from a name checked at run time', () => {
    const r = failsAt('niech n 10001\nnp 1\npowtorz n [np 1]', 3, 9);
    expect(r.segments.length).toBe(1);
    const r2 = failsAt('niech n 2\nnp 1\npowtorz n / 4 [np 1]', 3, 9);
    expect(r2.segments.length).toBe(1);
    const r3 = failsAt('niech n 0 - 1\nnp 1\npowtorz n [np 1]', 3, 9);
    expect(r3.segments.length).toBe(1);
  });
  test('missing body', () => {
    parseFailsAt('powtorz 3 np 1', 1, 11);
    parseFailsAt('np 1\npowtorz 3', 2, 1);
  });
  test('missing count', () => {
    parseFailsAt('powtorz [np 1]', 1, 9);
  });
  test('unbalanced brackets', () => {
    parseFails('powtorz 2 [np 1');
    parseFailsAt('np 1 ]', 1, 6);
    parseFailsAt(']', 1, 1);
    parseFails('powtorz 2 [np 1 [np 2]');
  });
  test('missing argument at ] inside body', () => {
    parseFailsAt('powtorz 2 [np]', 1, 14);
  });
});

describe('nrpowt', () => {
  test('iteration number starting at 1', () => {
    expect(len('powtorz 3 [np nrpowt]')).toEqual([1, 2, 3]);
    expect(len('repeat 3 [fd repcount * 2]')).toEqual([2, 4, 6]);
  });
  test('innermost enclosing repeat', () => {
    expect(len('powtorz 2 [powtorz 3 [np nrpowt]]')).toEqual([1, 2, 3, 1, 2, 3]);
  });
  test('after an inner repeat finishes it refers to the outer one', () => {
    expect(len('powtorz 2 [powtorz 1 [np 1] np nrpowt * 10]')).toEqual([1, 10, 1, 20]);
  });
  test('inside a conditional inside a repeat', () => {
    expect(len('powtorz 4 [jeśli nrpowt > 2 [np nrpowt]]')).toEqual([3, 4]);
  });
  test('count of a nested repeat refers to the outer repeat', () => {
    expect(ok('powtorz 3 [powtorz nrpowt [np 1]]').length).toBe(6);
  });
  test('outside any repeat at top level is a parse-time error', () => {
    parseFailsAt('np 1 np nrpowt', 1, 9);
    parseFailsAt('np 1 jeśli 1 = 1 [np nrpowt]', 1, 22);
    parseFailsAt('np 1 powtorz nrpowt [np 1]', 1, 14);
  });
  test('in a procedure body not inside a repeat is a parse-time error, even if called from a repeat', () => {
    parseFailsAt('oto p\nnp nrpowt\njuż\npowtorz 2 [p]', 2, 4);
    parseFailsAt('oto p\njeśli 1 = 1 [np repcount]\njuż\npowtorz 2 [p]', 2, 17);
  });
  test('in a procedure body inside a repeat is fine', () => {
    expect(len('oto p\npowtorz 2 [np nrpowt]\njuż\npowtorz 3 [p]')).toEqual([1, 2, 1, 2, 1, 2]);
  });
});

describe('variables', () => {
  test('assign and reassign', () => {
    expect(len('niech x 5 np x niech x x + 1 np x')).toEqual([5, 6]);
  });
  test('assigned from expressions with other variables', () => {
    expect(len('niech a 2 niech b a * 3 np b + a')).toEqual([8]);
  });
  test('global assigned inside a top-level repeat', () => {
    expect(len('powtorz 3 [niech x nrpowt] np x')).toEqual([3]);
  });
  test('top-level assignment after use is declared but unassigned at run time', () => {
    const r = failsAt('np 10 np x niech x 5', 1, 10);
    expect(dy(r.segments)).toEqual([10]);
  });
  test('unassigned on the current path', () => {
    const src = 'jeśli 1 = 2 [niech x 5]\nnp 10\nnp x';
    const r = failsAt(src, 3, 4);
    expect(r.segments.length).toBe(1);
    expect(len('jeśli 1 = 1 [niech x 5]\nnp 10\nnp x')).toEqual([10, 5]);
  });
  test('unassigned reported at the first token of the argument', () => {
    const r = failsAt('np 1 np 2 * x niech x 1', 1, 9);
    expect(r.segments.length).toBe(1);
    const r2 = failsAt('np 1 np (2 + x) niech x 1', 1, 9);
    expect(r2.segments.length).toBe(1);
    const r3 = failsAt('np 1 powtorz y [np 1] niech y 2', 1, 14);
    expect(r3.segments.length).toBe(1);
    const r4 = failsAt('np 1 jeśli x = 1 [np 1] niech x 2', 1, 12);
    expect(r4.segments.length).toBe(1);
  });
  test('undeclared name is a parse-time error', () => {
    parseFailsAt('np 10 np y', 1, 10);
    parseFailsAt('np 10 np :y', 1, 10);
    parseFailsAt('np 10\npowtorz 2 [np 1 + q]', 2, 20);
  });
  test('command words cannot be variable names', () => {
    parseFailsAt('np 1 niech np 5', 1, 12);
    parseFailsAt('np 1 niech powtorz 5', 1, 12);
    parseFailsAt('np 1 niech dom 5', 1, 12);
  });
  test('procedure names cannot be variable names', () => {
    parseFailsAt('oto p\nnp 1\njuż\nniech p 5', 4, 7);
  });
  test('missing or malformed niech arguments', () => {
    parseFailsAt('np 1 niech x', 1, 6);
    parseFailsAt('np 1 niech', 1, 6);
    parseFailsAt('np 1 niech 5 5', 1, 12);
  });
});

describe('conditionals', () => {
  test('jeśli runs body only when condition holds', () => {
    expect(len('jeśli 1 < 2 [np 1 np 2] jeśli 2 < 1 [np 3]')).toEqual([1, 2]);
  });
  test('jeżeli picks a branch', () => {
    expect(len('jeżeli 1 > 2 [np 10] [np 20]')).toEqual([20]);
    expect(len('jeżeli 1 < 2 [np 10] [np 20]')).toEqual([10]);
  });
  test('bodies may contain repeats, conditionals, calls and nrpowt (in repeat)', () => {
    const src = 'oto p\nnp 7\njuż\npowtorz 2 [jeżeli nrpowt = 1 [powtorz 2 [np 1]] [jeśli 1 = 1 [p]]]';
    expect(len(src)).toEqual([1, 1, 7]);
  });
  test('conditions with variables', () => {
    expect(len('niech a 3 jeśli a * 2 = 6 [np a]')).toEqual([3]);
  });
  test('missing body before a command', () => {
    parseFailsAt('jeśli 1 < 2 np 1', 1, 13);
  });
  test('missing second body at end of program reported at the command', () => {
    parseFailsAt('np 1\njeżeli 1 < 2 [np 1]', 2, 1);
  });
  test('missing body at end reported at the command', () => {
    parseFailsAt('np 1\njeśli 1 < 2', 2, 1);
    parseFailsAt('np 1\njeśli', 2, 1);
  });
  test('missing second body before a command', () => {
    parseFailsAt('jeżeli 1 < 2 [np 1] np 2', 1, 21);
  });
});

import { describe, expect, test } from 'bun:test';
import { ok, fails, failsAt, parseFails, parseFailsAt, closeSeg, dy } from './helpers';

const len = (src: string) => dy(ok(src));

describe('definitions and calls', () => {
  test('spec example: square', () => {
    const s = ok('oto kwadrat ma: bok, kąt
  powtorz 4 [np bok pw kąt]
już

kwadrat 80 90');
    expect(s.length).toBe(4);
    closeSeg(s[0], [0, 0, 0], [0, 80, 0]);
    closeSeg(s[1], [0, 80, 0], [80, 80, 0]);
    closeSeg(s[3], [80, 0, 0], [0, 0, 0]);
  });
  test('arguments are expressions: kwadrat 40 * 2 90', () => {
    const s = ok('oto kwadrat ma: bok, kąt
  powtorz 4 [np bok pw kąt]
już
kwadrat 40 * 2 90');
    expect(s.length).toBe(4);
    closeSeg(s[0], [0, 0, 0], [0, 80, 0]);
    closeSeg(s[1], [0, 80, 0], [80, 80, 0]);
  });
  test('legacy header with :params, referenced both ways', () => {
    expect(len('oto p :bok :kąt
np :bok
np bok
np kąt
już
p 3 4')).toEqual([3, 3, 4]);
  });
  test('ma: header params may be referenced as :name', () => {
    expect(len('oto p ma: a, b
np :a
np :b
już
p 3 4')).toEqual([3, 4]);
  });
  test('ma: params without spaces after comma', () => {
    expect(len('oto p ma: a,b
np a
np b
już
p 1 2')).toEqual([1, 2]);
  });
  test('procedure with no parameters', () => {
    expect(len('oto p
np 2
już
p p')).toEqual([2, 2]);
  });
  test('aliases to / end / juz', () => {
    expect(len('to p
fd 2
end
p')).toEqual([2]);
    expect(len('oto p
np 2
juz
p')).toEqual([2]);
    expect(len('TO p
np 2
END
p')).toEqual([2]);
  });
  test('definition after use', () => {
    expect(len('p 5
oto p ma: d
np d
już')).toEqual([5]);
  });
  test('unary argument after a whitespace-separated value is a new argument', () => {
    expect(len('oto p ma: a, b
np a
np b
już
p 10 -5')).toEqual([10, -5]);
  });
  test('binary argument expression consumes the following value', () => {
    // `10 - 5` is one argument; the second one is missing at end of program
    parseFailsAt('oto p ma: a, b
np a
np b
już
p 10 - 5', 5, 1);
  });
  test('parenthesised arguments', () => {
    expect(len('oto p ma: a, b
np a
np b
już
p (1 + 1) (2 * 2)')).toEqual([2, 4]);
  });
  test('parameters as repeat counts and as arguments of other calls', () => {
    const src = 'oto a ma: n
np n
już
oto b ma: m
powtorz m [a m * 2]
już
b 3';
    expect(len(src)).toEqual([6, 6, 6]);
  });
  test('parameter may share its name with a procedure', () => {
    const src = 'oto a ma: b
np b
już
oto b ma: a
a a
już
b 7';
    expect(len(src)).toEqual([7]);
  });
  test('procedure name in argument position is not a value', () => {
    parseFailsAt('oto p
np 1
już
np p', 4, 4);
  });
});

describe('arity', () => {
  const def = 'oto p ma: a, b
np a
np b
już
';
  test('too few at end of program reported at the call', () => {
    parseFailsAt(def + 'np 1
p 1', 6, 1);
  });
  test('too few before a command reported at that command', () => {
    parseFailsAt(def + 'p 1
np 2', 6, 1);
  });
  test('too few before ] reported at ]', () => {
    parseFailsAt(def + 'powtorz 2 [p 1]', 5, 15);
  });
  test('too many: stray value reported at that value', () => {
    parseFailsAt(def + 'p 1 2 3', 5, 7);
  });
  test('zero-parameter procedure given an argument', () => {
    parseFailsAt('oto q
np 1
już
q 5', 4, 3);
  });
  test('arity checked even when the definition comes after the call', () => {
    parseFailsAt('np 1
p 1 2 3
oto p ma: a, b
np a
już', 2, 5);
  });
});

describe('recursion', () => {
  test('direct recursion', () => {
    const src = 'oto spirala ma: n
jeśli n > 0 [np n pw 90 spirala n - 1]
już
spirala 3';
    const s = ok(src);
    expect(s.length).toBe(3);
    closeSeg(s[0], [0, 0, 0], [0, 3, 0]);
    closeSeg(s[1], [0, 3, 0], [2, 3, 0]);
    closeSeg(s[2], [2, 3, 0], [2, 2, 0]);
  });
  test('mutual recursion', () => {
    const src = 'oto a ma: n
jeśli n > 0 [np 1 b n - 1]
już
oto b ma: n
jeśli n > 0 [np 2 a n - 1]
już
a 4';
    expect(len(src)).toEqual([1, 2, 1, 2]);
  });
  test('each call has its own locals', () => {
    const src = 'oto r ma: n
niech x n * 10
jeśli n > 0 [r n - 1]
np x
już
r 2';
    expect(len(src)).toEqual([0, 10, 20]);
  });
});

describe('stop', () => {
  test('ends the current call, caller continues', () => {
    expect(len('oto p
np 1
stop
np 2
już
p
np 3')).toEqual([1, 3]);
  });
  test('only the innermost call ends', () => {
    expect(len('oto a
np 1
b
np 3
już
oto b
np 2
stop
np 9
już
a')).toEqual([1, 2, 3]);
  });
  test('inside repeat and conditional bodies it ends the whole call', () => {
    const src = 'oto p
powtorz 5 [np 1 jeśli nrpowt = 2 [stop]]
np 100
już
powtorz 2 [p np 10]';
    expect(len(src)).toEqual([1, 1, 10, 1, 1, 10]);
  });
  test('inside jeżeli body in a procedure', () => {
    expect(len('oto p ma: n
jeżeli n > 1 [stop] [np n]
np 5
już
p 2
p 1')).toEqual([1, 5]);
  });
  test('called from a repeat it does not stop the repeat', () => {
    expect(len('oto p
np 1
stop
już
powtorz 3 [p np 2]')).toEqual([1, 2, 1, 2, 1, 2]);
  });
});

describe('scoping', () => {
  test('local niech shadows global and is discarded', () => {
    expect(len('niech x 10
oto p
niech x 20
np x
już
p
np x')).toEqual([20, 10]);
  });
  test('shadowing applies for the rest of the call only', () => {
    expect(len('niech x 10
oto p
np x
niech x 20
np x
już
p
np x')).toEqual([10, 20, 10]);
  });
  test('procedure reads a global', () => {
    expect(len('niech g 7
oto p
np g
już
p')).toEqual([7]);
  });
  test('global assigned after definition but before call', () => {
    expect(len('oto p
np g
już
niech g 5
p')).toEqual([5]);
  });
  test('global updated between calls', () => {
    expect(len('oto p
np g
już
niech g 1
p
niech g 2
p')).toEqual([1, 2]);
  });
  test('global assigned only after the call is unassigned at run time', () => {
    const r = failsAt('oto p
np g
już
np 1
p
niech g 5', 2, 4);
    expect(r.segments.length).toBe(1);
  });
  test('parameter shadows a global', () => {
    expect(len('niech a 1
oto p :a
np a
już
p 5
np a')).toEqual([5, 1]);
  });
  test('parameter can be reassigned', () => {
    expect(len('oto p :a
niech a a * 2
np a
już
p 5')).toEqual([10]);
  });
  test('locals of one procedure are not visible in another', () => {
    parseFailsAt('oto a
niech y 5
b
już
oto b
np y
już
a', 6, 4);
  });
  test('locals are not visible at top level', () => {
    parseFailsAt('oto a
niech y 5
już
a
np y', 5, 4);
  });
  test('parameters are not visible at top level', () => {
    parseFailsAt('oto a ma: k
np k
już
a 1
np k', 5, 4);
  });
  test('locals are discarded when the call ends', () => {
    const src = 'oto p ma: first
jeśli first = 1 [niech v 5]
np v
już
p 1
p 0';
    const r = failsAt(src, 3, 4);
    expect(dy(r.segments)).toEqual([5]);
  });
  test('unassigned local is a run-time error', () => {
    const r = failsAt('oto p
np 10
np z
niech z 1
już
p', 3, 4);
    expect(r.segments.length).toBe(1);
  });
  test('top-level niech inside repeat creates a global visible in procedures', () => {
    expect(len('oto p
np g
już
powtorz 2 [niech g nrpowt]
p')).toEqual([2]);
  });
  test('niech inside procedure does not change the global', () => {
    expect(len('niech x 1
oto p
powtorz 2 [niech x 9]
już
p
np x')).toEqual([1]);
  });
});

describe('definition errors', () => {
  test('a name may be defined once', () => {
    const r = parseFails('oto p
np 1
już
oto p
np 2
już
p');
    expect(r.error!.line).toBe(4);
  });
  test('duplicate definitions differing only in case', () => {
    const r = parseFails('oto p
np 1
już
oto P
np 2
już');
    expect(r.error!.line).toBe(4);
  });
  test('definition inside a repeat body', () => {
    parseFailsAt('np 1
powtorz 2 [
oto p
np 1
już
]', 3, 1);
  });
  test('definition inside a conditional body', () => {
    parseFailsAt('np 1
jeśli 1 = 1 [
oto p
np 1
już
]', 3, 1);
  });
  test('definition inside another procedure', () => {
    parseFailsAt('np 1
oto a
oto b
np 1
już
już
a', 3, 1);
  });
  test('missing już', () => {
    parseFails('np 1
oto p
np 1
');
    parseFails('np 1
oto p ma: a
np a');
  });
  test('już must be alone on its line', () => {
    parseFails('np 1
oto p
np 1 już
p');
  });
  test('oto must start a line', () => {
    parseFails('np 1 oto p
np 1
już');
  });
  test('procedure name may not be a command word', () => {
    const r = parseFails('np 1
oto np
np 1
już');
    expect(r.error!.line).toBe(2);
  });
  test('unknown command in a never-called procedure is a parse-time error', () => {
    parseFailsAt('np 1
oto p
  np 10
  foo
już', 4, 3);
  });
  test('run-time error inside a procedure keeps earlier drawing', () => {
    const r = failsAt('oto p ma: d
np 10 / d
już
p 2
p 0', 2, 4);
    expect(r.segments.length).toBe(1);
    closeSeg(r.segments[0], [0, 0, 0], [0, 5, 0]);
  });
  test('call of an undefined procedure', () => {
    parseFailsAt('np 1
kwadrat 10', 2, 1);
  });
  test('header without a name', () => {
    fails('oto
np 1
już');
  });
});

