import re,subprocess,os
want="libglib2.0-0 libnspr4 libnss3 libatk1.0-0 libdbus-1-3 libx11-6 libxcomposite1 libxdamage1 libxext6 libxfixes3 libxrandr2 libgbm1 libxcb1 libxkbcommon0 libasound2 libatspi2.0-0 libxau6 libxdmcp6 libwayland-server0 libdrm2 libbsd0 libmd0 libxrender1 libxi6 libsystemd0 libffi8 libpcre2-8-0 libmount1 libselinux1 libblkid1 libexpat1 libz3-4".split()
pk={}
cur={}
for block in open('Packages',encoding='utf-8',errors='replace').read().split('\n\n'):
    m=re.search(r'^Package: (.+)$',block,re.M); f=re.search(r'^Filename: (.+)$',block,re.M)
    if m and f: pk[m.group(1)]=f.group(1)
for w in want:
    if w in pk:
        url='http://deb.debian.org/debian/'+pk[w]
        subprocess.run(['curl','-sSfL','-o',os.path.basename(pk[w]),url])
    else: print('missing',w)
EOF
