await page.goto(base);
await page.waitForTimeout(400);
for (let i = 0; i < 26; i++) {
  await page.keyboard.press('Tab');
  focused.push(await page.evaluate(() => { const a = document.activeElement; return a ? (a.getAttribute('aria-label') || a.textContent.trim().slice(0, 20) || a.tagName) : '-'; }));
}
