await page.goto(base + '#/');
await page.locator('.seg-btn', { hasText: 'Szkic 3D' }).click();
await page.waitForTimeout(800);
await page.keyboard.press('Control+Enter');
await page.waitForTimeout(3000);
await page.locator('.stage-3d canvas').focus();
for (let i = 0; i < 4; i++) await page.keyboard.press('ArrowLeft');
await page.keyboard.press('ArrowUp');
await page.waitForTimeout(300);
await page.screenshot({ path: '/tmp/shots/dark-3d.png' });
// PNG export
const [dl] = await Promise.all([page.waitForEvent('download'), page.locator('button[aria-label="Zapisz rysunek jako PNG"]').click()]);
console.log('download', dl.suggestedFilename(), (await import('fs')).statSync(await dl.path()).size);
const [dl2] = await Promise.all([page.waitForEvent('download'), page.locator('button[aria-label="Pobierz program jako plik .logo"]').click()]);
console.log('download', dl2.suggestedFilename(), (await import('fs')).readFileSync(await dl2.path(), 'utf8').slice(0, 30));
// open file
await page.locator('input[type=file]').setInputFiles({ name: 'test.logo', mimeType: 'text/plain', buffer: Buffer.from('np 50 pw 90 np 50') });
await page.waitForTimeout(600);
console.log('dialog after open file', await page.locator('dialog[open]').count(), await page.locator('.seg-btn[aria-pressed=true]').innerText());
await page.screenshot({ path: '/tmp/shots/openfile.png' });
// Mobile
const m = await browser.newContext({ viewport: { width: 390, height: 780 }, isMobile: true, hasTouch: true });
const mp = await m.newPage();
await mp.goto(base + '#/wyzwanie/dwa-kwadraty');
