206	  private onKey(e: KeyboardEvent): void {
207	    const ta = this.textarea;
208	    if (e.key === 'Escape') {
209	      this.tabMovesFocus = true;
210	      return;
211	    }
212	    if (e.key === 'Tab' && !e.ctrlKey && !e.altKey && !e.metaKey) {
213	      if (this.tabMovesFocus) return;
214	      e.preventDefault();
215	      const { selectionStart: s, selectionEnd: end, value } = ta;
216	      const lineStart = value.lastIndexOf('\n', s - 1) + 1;
217	      if (e.shiftKey) {
218	        // Zmniejsz wcięcie bieżącego wiersza.
219	        const m = /^ {1,2}/.exec(value.slice(lineStart));
220	        if (m) {
