222	          this.insert('');
223	          const ns = Math.max(lineStart, s - m[0].length);
224	          ta.setSelectionRange(ns, Math.max(ns, end - m[0].length));
225	        }
226	        return;
227	      }
228	      if (s !== end && value.slice(s, end).includes('\n')) {
229	        // Wcięcie wielu wierszy.
230	        const block = value.slice(lineStart, end);
231	        const indented = block.replace(/^/gm, '  ');
232	        ta.setSelectionRange(lineStart, end);
233	        this.insert(indented);
234	        ta.setSelectionRange(lineStart, lineStart + indented.length);
235	        return;
236	      }
237	      this.insert('  ');
238	      return;
239	    }
240	    this.tabMovesFocus = false;
241	    if (e.key === 'Enter' && !e.ctrlKey && !e.metaKey && !e.altKey && !e.shiftKey && !e.isComposing) {
242	      const { selectionStart: s, value } = ta;
243	      const lineStart = value.lastIndexOf('\n', s - 1) + 1;
244	      const before = value.slice(lineStart, s);
245	      let indent = /^[ \t]*/.exec(before)![0];
246	      const trimmed = before.replace(/;.*$/, '').trimEnd();
247	      if (trimmed.endsWith('[')) indent += '  ';
248	      else if (/^\s*(oto|to)\s/i.test(before)) indent += '  ';
249	      e.preventDefault();
250	      this.insert('\n' + indent);
251	      return;
252	    }
253	    if (e.key === ']' && !e.ctrlKey && !e.metaKey) {
254	      // Zamykający nawias w pustym wierszu cofa wcięcie.
255	      const { selectionStart: s, selectionEnd: end, value } = ta;
256	      const lineStart = value.lastIndexOf('\n', s - 1) + 1;
257	      const before = value.slice(lineStart, s);
258	      if (s === end && /^ {2,}$/.test(before)) {
259	        e.preventDefault();
260	        ta.setSelectionRange(s - 2, s);
261	        this.insert(']');
262	      }
263	    }
264	  }
