266	import { lex, type Token } from '../lang/lexer';
267	import { escapeHtml } from './dom';
268	
269	const CONTROL = new Set(['repeat', 'if', 'ifelse', 'stop', 'to', 'end', 'let']);
270	
271	function tokenClass(t: Token, procs: Set<string>, depth: number): string {
272	  switch (t.kind) {
273	    case 'num': return 'tk-num';
274	    case 'str': return /^#[0-9a-fA-F]{6}$/.test(t.str!) ? 'tk-str' : 'tk-bad';
275	    case 'lbr': case 'rbr': return `tk-br tk-d${depth % 3}`;
276	    case 'lpar': case 'rpar': return 'tk-par';
277	    case 'op': case 'cmp': return 'tk-op';
278	    case 'comma': return 'tk-op';
279	    case 'bad': return 'tk-bad';
280	    case 'word':
281	      if (t.name === 'ma:') return 'tk-ctl';
282	      if (t.keyword === 'repcount') return 'tk-val';
283	      if (t.keyword) return CONTROL.has(t.keyword) ? 'tk-ctl' : 'tk-cmd';
284	      if (!t.colon && procs.has(t.name!)) return 'tk-proc';
285	      return 'tk-name';
286	  }
287	}
