289	export interface HighlightMark {
290	  /** Przesunięcia w źródle. */
291	  start: number;
292	  end: number;
293	  cls: string;
294	  /** Dopisek na końcu wiersza (np. treść błędu). */
295	  note?: string;
296	}
297	
298	/**
299	 * Zamienia źródło na HTML z kolorowaniem składni. Zwraca tablicę wierszy
300	 * (bez znaków nowego wiersza), żeby edytor mógł je łatwo złożyć.
301	 */
302	export function highlightLines(source: string, mark?: HighlightMark | null): string[] {
303	  const { tokens, comments } = lex(source);
304	  const procs = new Set<string>();
305	  for (let k = 0; k < tokens.length - 1; k++) {
306	    const t = tokens[k]!;
307	    if (t.kind === 'word' && t.keyword === 'to' && t.firstOnLine) {
308	      const n = tokens[k + 1]!;
309	      if (n.kind === 'word' && n.line === t.line && !n.keyword) procs.add(n.name!);
310	    }
311	  }
312	  // Przedziały do pokolorowania, posortowane po początku.
313	  type Span = { start: number; end: number; cls: string; style?: string };
314	  const spans: Span[] = [];
315	  let depth = 0;
316	  for (const t of tokens) {
317	    let d = depth;
318	    if (t.kind === 'lbr') { d = depth; depth++; }
319	    else if (t.kind === 'rbr') { depth = Math.max(0, depth - 1); d = depth; }
320	    const span: Span = { start: t.start, end: t.end, cls: tokenClass(t, procs, d) };
321	    if (t.kind === 'str' && span.cls === 'tk-str') span.style = `--swatch:${t.str!.toLowerCase()}`;
322	    spans.push(span);
323	  }
324	  for (const c of comments) spans.push({ start: c.start, end: c.end, cls: 'tk-com' });
325	  spans.sort((a, b) => a.start - b.start);
326	
327	  // Wynik budujemy znak po znaku przez przedziały, dzieląc na wiersze.
328	  const out: string[] = [];
329	  let line = '';
330	  let pos = 0;
331	  const emitText = (text: string, cls?: string, style?: string) => {
332	    const parts = text.split(/\r\n|\r|\n/);
333	    parts.forEach((p, idx) => {
334	      if (idx > 0) { out.push(line); line = ''; }
335	      if (!p) return;
336	      const e = escapeHtml(p);
337	      line += cls ? `<span class="${cls}"${style ? ` style="${style}"` : ''}>${e}</span>` : e;
338	    });
339	  };
340	  const markStart = mark ? mark.start : -1;
341	  const markEnd = mark ? Math.max(mark.end, mark.start + 1) : -1;
342	  const emitRange = (from: number, to: number, cls?: string, style?: string) => {
343	    // Dzieli fragment na część przed znacznikiem, w znaczniku i po nim.
344	    if (mark && from < markEnd && to > markStart) {
345	      const a = Math.max(from, markStart), b = Math.min(to, markEnd);
346	      if (from < a) emitText(source.slice(from, a), cls, style);
347	      emitText(source.slice(a, b), `${cls ?? ''} ${mark.cls}`.trim(), style);
348	      if (b < to) emitText(source.slice(b, to), cls, style);
349	    } else {
350	      emitText(source.slice(from, to), cls, style);
351	    }
352	  };
353	  for (const sp of spans) {
354	    if (sp.start < pos) continue;
355	    if (sp.start > pos) emitRange(pos, sp.start);
356	    emitRange(sp.start, sp.end, sp.cls, sp.style);
357	    pos = sp.end;
358	  }
359	  if (pos < source.length) emitRange(pos, source.length);
360	  // Znacznik za końcem tekstu (np. błąd na końcu programu).
361	  if (mark && markStart >= source.length) line += `<span class="${mark.cls} mark-eol"> </span>`;
362	  out.push(line);
363	  return out;
364	}
365	
366	/** Statyczny blok kodu (np. w dokumentacji). */
367	export function highlightBlock(source: string): string {
368	  return highlightLines(source.replace(/\n$/, '')).join('\n');
369	}

