198	  private bindInput(): void {
199	    const c = this.canvas;
200	    const local = (e: { clientX: number; clientY: number }) => {
201	      const r = c.getBoundingClientRect();
202	      return { x: e.clientX - r.left, y: e.clientY - r.top };
203	    };
204	    c.addEventListener('pointerdown', (e) => {
205	      c.setPointerCapture(e.pointerId);
206	      this.pointers.set(e.pointerId, local(e));
207	      if (this.pointers.size === 2) this.pinch = this.pinchState();
208	    });
209	    c.addEventListener('pointermove', (e) => {
210	      const prev = this.pointers.get(e.pointerId);
211	      if (!prev) return;
212	      const p = local(e);
213	      this.pointers.set(e.pointerId, p);
214	      if (this.pointers.size === 1) {
215	        this.panBy(p.x - prev.x, p.y - prev.y);
216	      } else if (this.pointers.size === 2 && this.pinch) {
217	        const now = this.pinchState();
218	        this.panBy(now.cx - this.pinch.cx, now.cy - this.pinch.cy);
219	        if (this.pinch.dist > 0) this.zoom(now.dist / this.pinch.dist, { x: now.cx, y: now.cy });
220	        this.pinch = now;
221	      }
222	    });
223	    const up = (e: PointerEvent) => {
224	      this.pointers.delete(e.pointerId);
225	      this.pinch = this.pointers.size === 2 ? this.pinchState() : null;
226	    };
227	    c.addEventListener('pointerup', up);
228	    c.addEventListener('pointercancel', up);
229	    c.addEventListener('wheel', (e) => {
230	      e.preventDefault();
231	      const dy = e.deltaMode === 1 ? e.deltaY * 16 : e.deltaY;
232	      this.zoom(Math.exp(-dy * 0.0015), local(e));
233	    }, { passive: false });
234	    c.addEventListener('dblclick', () => this.fit());
235	    c.addEventListener('keydown', (e) => {
236	      if (e.ctrlKey || e.metaKey || e.altKey) return;
237	      const step = 40;
238	      switch (e.key) {
239	        case 'ArrowLeft': this.panBy(step, 0); break;
240	        case 'ArrowRight': this.panBy(-step, 0); break;
241	        case 'ArrowUp': this.panBy(0, step); break;
242	        case 'ArrowDown': this.panBy(0, -step); break;
243	        case '+': case '=': this.zoom(1.25); break;
244	        case '-': case '_': this.zoom(0.8); break;
245	        case '0': case 'f': case 'F': this.fit(); break;
246	        default: return;
247	      }
248	      e.preventDefault();
249	    });
250	  }
