316	// Odnośnik do programu: #/kod/<tryb>/<dane>. Dane to „z” + base64url
317	// skompresowanego tekstu albo „t” + base64url samego tekstu UTF-8.
318	
319	function toBase64Url(bytes: Uint8Array): string {
320	  let bin = '';
321	  for (let i = 0; i < bytes.length; i += 0x8000) {
322	    bin += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
323	  }
324	  return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
325	}
326	
327	function fromBase64Url(s: string): Uint8Array {
328	  const b64 = s.replace(/-/g, '+').replace(/_/g, '/') + '==='.slice((s.length + 3) % 4);
329	  const bin = atob(b64);
330	  const out = new Uint8Array(bin.length);
331	  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
332	  return out;
333	}
334	
335	async function pipe(bytes: Uint8Array, stream: CompressionStream | DecompressionStream): Promise<Uint8Array> {
336	  const blob = new Blob([bytes as BlobPart]);
337	  const res = new Response(blob.stream().pipeThrough(stream));
338	  return new Uint8Array(await res.arrayBuffer());
339	}
340	
341	export async function encodeProgram(source: string): Promise<string> {
342	  const raw = new TextEncoder().encode(source);
343	  const plain = 't' + toBase64Url(raw);
344	  if (typeof CompressionStream === 'undefined') return plain;
345	  try {
346	    const packed = 'z' + toBase64Url(await pipe(raw, new CompressionStream('deflate-raw')));
347	    return packed.length < plain.length ? packed : plain;
348	  } catch {
349	    return plain;
350	  }
351	}
352	
353	export async function decodeProgram(payload: string): Promise<string | null> {
354	  try {
355	    const kind = payload[0];
356	    const bytes = fromBase64Url(payload.slice(1));
357	    if (kind === 't') return new TextDecoder('utf-8', { fatal: true }).decode(bytes);
358	    if (kind === 'z' && typeof DecompressionStream !== 'undefined') {
359	      return new TextDecoder('utf-8', { fatal: true }).decode(await pipe(bytes, new DecompressionStream('deflate-raw')));
360	    }
361	  } catch {
362	    /* uszkodzony odnośnik */
363	  }
364	  return null;
365	}
366	
367	export async function permalink(source: string, mode: Mode): Promise<string> {
368	  const url = new URL(window.location.href);
369	  url.hash = `#/kod/${mode}/${await encodeProgram(source)}`;
370	  return url.toString();
371	}
