155	  private fitTo(segments: readonly Segment[], points: Vec3[], resetDirection: boolean): void {
156	    const box = new THREE.Box3();
157	    const v = new THREE.Vector3();
158	    for (const s of segments) {
159	      box.expandByPoint(v.set(...s.from));
160	      box.expandByPoint(v.set(...s.to));
161	    }
162	    for (const p of points) box.expandByPoint(v.set(...p));
163	    if (box.isEmpty()) box.set(new THREE.Vector3(-100, -20, 0), new THREE.Vector3(100, 140, 80));
164	    const sphere = box.getBoundingSphere(new THREE.Sphere());
165	    const radius = Math.max(sphere.radius, 20);
166	    const fov = (this.camera.fov * Math.PI) / 180;
167	    const fitH = radius / Math.sin(fov / 2);
168	    const fitW = radius / Math.sin(Math.atan(Math.tan(fov / 2) * this.camera.aspect));
169	    const dist = Math.max(fitH, fitW) * 1.08;
170	    const dir = resetDirection
171	      ? DEFAULT_DIR.clone()
172	      : this.camera.position.clone().sub(this.controls.target).normalize();
173	    this.controls.target.copy(sphere.center);
174	    this.camera.position.copy(sphere.center).addScaledVector(dir, dist);
175	    this.camera.near = Math.max(0.1, dist / 500);
176	    this.camera.far = dist * 50 + radius * 10;
177	    this.camera.updateProjectionMatrix();
178	    this.controls.update();
179	    const extent = Math.max(Math.abs(box.min.x), Math.abs(box.max.x), Math.abs(box.min.y), Math.abs(box.max.y), radius);
180	    this.buildHelpers(extent * 2.4);
181	    this.schedule();
182	  }
