188	  private buildHelpers(size: number, force = false): void {
189	    const step = niceStep(size / 16);
190	    const total = Math.max(step * 8, Math.ceil(size / step / 2) * step * 2);
191	    if (!force && Math.abs(total - this.gridSize) < 1e-9) return;
192	    this.gridSize = total;
193	    for (const child of [...this.helpers.children]) {
194	      this.helpers.remove(child);
195	      disposeObject(child);
196	    }
197	    const divisions = Math.round(total / step);
198	    const grid = new THREE.GridHelper(total, divisions, this.palette.gridStrong, this.palette.grid);
199	    grid.rotation.x = Math.PI / 2;
200	    this.helpers.add(grid);
201	    const L = Math.max(step * 2, total * 0.18);
202	    const axis = (to: THREE.Vector3, color: string, label: string) => {
203	      const g = new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(), to]);
204	      const line = new THREE.Line(g, new THREE.LineBasicMaterial({ color }));
205	      this.helpers.add(line);
206	      const sprite = makeLabel(label, color);
207	      sprite.position.copy(to).multiplyScalar(1.08);
208	      this.helpers.add(sprite);
209	    };
210	    axis(new THREE.Vector3(L, 0, 0), this.palette.axisX, 'X');
211	    axis(new THREE.Vector3(0, L, 0), this.palette.axisY, 'Y');
212	    axis(new THREE.Vector3(0, 0, L), this.palette.axisZ, 'Z');
213	    const origin = new THREE.Mesh(
214	      new THREE.SphereGeometry(1, 12, 8),
215	      new THREE.MeshBasicMaterial({ color: this.palette.text }),
216	    );
217	    origin.scale.setScalar(Math.max(1, step / 30));
218	    this.helpers.add(origin);
219	  }
