221	  private makeTurtle(): THREE.Group {
222	    const g = new THREE.Group();
223	    // Grot: nos wzdłuż +Y, płetwa wzdłuż +Z (góra żółwia), boki wzdłuż ±X.
224	    const T = [0, 12, 0], L = [-7, -6, 0], R = [7, -6, 0], U = [0, -4, 5.5], B = [0, -3.5, -2];
225	    const faces = [T, U, L, T, R, U, T, L, B, T, B, R, L, U, R, L, R, B];
226	    const geom = new THREE.BufferGeometry();
227	    geom.setAttribute('position', new THREE.Float32BufferAttribute(faces.flat(), 3));
228	    geom.computeVertexNormals();
