241	  private updateTurtle(): void {
242	    const t = this.frame.turtle;
243	    if (!t) { this.turtle.visible = false; return; }
244	    this.turtle.visible = true;
245	    const dist = this.camera.position.distanceTo(this.controls.target);
246	    const s = Math.max(0.05, dist / 420);
247	    const m = new THREE.Matrix4().makeBasis(
248	      new THREE.Vector3(...t.r), new THREE.Vector3(...t.h), new THREE.Vector3(...t.u),
249	    );
250	    m.scale(new THREE.Vector3(s, s, s));
251	    m.setPosition(t.pos[0], t.pos[1], t.pos[2]);
252	    this.turtle.matrix.copy(m);
253	    this.turtle.matrixWorldNeedsUpdate = true;
254	    const mat = this.turtleBody.material as THREE.MeshStandardMaterial;
255	    mat.color.set(t.color);
256	    mat.opacity = t.pen ? 0.95 : 0.35;
257	    const edges = this.turtle.children[1] as THREE.LineSegments;
258	    (edges.material as THREE.LineBasicMaterial).color.set(this.palette.turtle);
259	  }
