261	  private rebuildDrawing(): void {
262	    const f = this.frame;
263	    if (f.segments !== this.builtSegments || f.segments.length !== this.builtCount) {
264	      this.builtSegments = f.segments;
265	      this.builtCount = f.segments.length;
266	      this.replaceLines(this.drawing, f.segments);
267	    }
268	    this.replaceLines(this.partialGroup, f.partial ? [f.partial] : []);
269	    if (f.ghost !== this.builtGhost) {
270	      this.builtGhost = f.ghost;
271	      this.replaceLines(this.ghostGroup, f.ghost ?? [], true);
272	    }
273	  }
