275	  private replaceLines(group: THREE.Group, segments: readonly Segment[], ghost = false): void {
276	    for (const child of [...group.children]) {
277	      group.remove(child);
278	      const line = child as LineSegments2;
279	      this.materials.delete(line.material);
280	      disposeObject(child);
281	    }
282	    if (!segments.length) return;
283	    const byWidth = new Map<number, Segment[]>();
284	    for (const s of segments) {
285	      const w = ghost ? 5 : s.width;
286	      let list = byWidth.get(w);
287	      if (!list) byWidth.set(w, (list = []));
288	      list.push(s);
289	    }
290	    const color = new THREE.Color();
291	    for (const [width, list] of byWidth) {
292	      const pos = new Float32Array(list.length * 6);
293	      const col = new Float32Array(list.length * 6);
294	      list.forEach((s, k) => {
295	        pos.set(s.from, k * 6);
296	        pos.set(s.to, k * 6 + 3);
297	        color.set(s.color);
298	        col[k * 6] = col[k * 6 + 3] = color.r;
299	        col[k * 6 + 1] = col[k * 6 + 4] = color.g;
300	        col[k * 6 + 2] = col[k * 6 + 5] = color.b;
301	      });
302	      const geom = new LineSegmentsGeometry();
303	      geom.setPositions(pos);
304	      const mat = ghost
305	        ? new LineMaterial({ color: new THREE.Color(this.palette.ghost.startsWith('#') ? this.palette.ghost : '#a89f8a'), linewidth: width, dashed: true, dashSize: 6, gapSize: 6, transparent: true, opacity: 0.55, depthWrite: false })
306	        : new LineMaterial({ vertexColors: true, linewidth: width });
307	      if (!ghost) geom.setColors(col);
308	      mat.resolution.set(this.width, this.height);
309	      const line = new LineSegments2(geom, mat);
310	      if (ghost) line.computeLineDistances();
311	      this.materials.add(mat);
312	      group.add(line);
313	    }
314	  }
