316	  private updateResolution(): void {
317	    const size = this.renderer.getDrawingBufferSize(new THREE.Vector2());
318	    const ratio = this.renderer.getPixelRatio();
319	    for (const m of this.materials) m.resolution.set(size.x / ratio, size.y / ratio);
320	  }
