349	  private bindKeys(canvas: HTMLCanvasElement): void {
350	    canvas.addEventListener('keydown', (e) => {
351	      if (e.ctrlKey || e.metaKey || e.altKey) return;
352	      const target = this.controls.target;
353	      const offset = this.camera.position.clone().sub(target);
354	      const sph = new THREE.Spherical();
355	      // Sferyczne współrzędne liczone względem osi Z (góra).
356	      const toYUp = (v: THREE.Vector3) => new THREE.Vector3(v.x, v.z, -v.y);
357	      const fromYUp = (v: THREE.Vector3) => new THREE.Vector3(v.x, -v.z, v.y);
358	      sph.setFromVector3(toYUp(offset));
359	      const rot = Math.PI / 18;
360	      const panStep = offset.length() * 0.06;
361	      const pan = (dx: number, dy: number) => {
362	        this.autoFit = false;
363	        const right = new THREE.Vector3().setFromMatrixColumn(this.camera.matrix, 0);
364	        const up = new THREE.Vector3().setFromMatrixColumn(this.camera.matrix, 1);
365	        const delta = right.multiplyScalar(dx * panStep).add(up.multiplyScalar(dy * panStep));
366	        target.add(delta);
367	        this.camera.position.add(delta);
368	        this.controls.update();
369	      };
370	      switch (e.key) {
371	        case 'ArrowLeft': if (e.shiftKey) pan(-1, 0); else sph.theta -= rot; break;
372	        case 'ArrowRight': if (e.shiftKey) pan(1, 0); else sph.theta += rot; break;
373	        case 'ArrowUp': if (e.shiftKey) pan(0, 1); else sph.phi = Math.max(0.05, sph.phi - rot); break;
374	        case 'ArrowDown': if (e.shiftKey) pan(0, -1); else sph.phi = Math.min(Math.PI - 0.05, sph.phi + rot); break;
375	        case '+': case '=': this.zoom(1.25); e.preventDefault(); return;
376	        case '-': case '_': this.zoom(0.8); e.preventDefault(); return;
377	        case '0': case 'f': case 'F': this.fit(); e.preventDefault(); return;
378	        case 'r': case 'R': this.resetView(); e.preventDefault(); return;
379	        default: return;
380	      }
381	      e.preventDefault();
382	      if (!e.shiftKey) {
383	        this.camera.position.copy(target).add(fromYUp(new THREE.Vector3().setFromSpherical(sph)));
384	        this.controls.update();
385	      }
386	    });
387	  }
388	}
