390	function niceStep(raw: number): number {
391	  const exp = Math.floor(Math.log10(Math.max(raw, 1e-6)));
392	  const base = 10 ** exp;
393	  for (const n of [1, 2, 5, 10]) if (n * base >= raw) return n * base;
394	  return 10 * base;
395	}
