/* ------------------------------------------------------------------
   Logomocja – kolory, typografia, układ
   ------------------------------------------------------------------ */

:root {
  --font-ui: system-ui, -apple-system, "Segoe UI", Roboto, "Noto Sans", "Helvetica Neue", Arial, sans-serif;
  --font-code: ui-monospace, "Cascadia Mono", "JetBrains Mono", "SF Mono", Menlo, Consolas, "DejaVu Sans Mono", "Liberation Mono", monospace;
  --radius: 12px;
  --radius-s: 8px;
  --topbar-h: 56px;
  --code-size: 14px;
  --code-lh: 22px;
  color-scheme: light;

  --bg: #f4efe4;
  --surface: #fffdf8;
  --surface-2: #f7f1e5;
  --surface-3: #efe7d7;
  --border: #e0d6c2;
  --border-strong: #cdbfa5;
  --text: #1d2a27;
  --muted: #625f55;
  --accent: #127a60;
  --accent-hover: #0e6750;
  --accent-soft: #dcefe7;
  --accent-contrast: #ffffff;
  --accent-2: #b4692f;
  --accent-2-soft: #f6e6d6;
  --danger: #b03a26;
  --danger-bg: #fbe7e2;
main:focus { outline: none; }
.page { flex: 1; min-height: 0; }

.page-studio { display: flex; flex-direction: column; }

.studio {
  flex: 1;
  display: grid;
  grid-template-columns: minmax(340px, 0.92fr) minmax(0, 1.08fr);
  grid-template-areas: "editor stage";
  gap: 14px;
  padding: 14px;
  height: calc(100vh - var(--topbar-h));
  height: calc(100dvh - var(--topbar-h));
  min-height: 520px;
}

.pane { display: flex; flex-direction: column; min-width: 0; min-height: 0; gap: 10px; }
.editor-pane { grid-area: editor; }
.stage-pane { grid-area: stage; }

.pane-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; flex-wrap: wrap; }
.file-actions { display: flex; gap: 6px; }

.seg {
  display: inline-flex; gap: 2px; padding: 3px;
  background: var(--surface-3);
  border-radius: 10px;
  min-width: 0;
}
.seg-btn {
  border: 0; background: transparent; color: var(--muted);
  font: 600 13.5px/1 var(--font-ui);
  padding: 9px 12px;
  border-radius: 8px;
  cursor: pointer;
  white-space: nowrap;
}
.seg-btn:hover { color: var(--text); }
.seg-btn[aria-pressed="true"] { background: var(--surface); color: var(--accent); box-shadow: 0 1px 3px rgba(0, 0, 0, .12); }
.seg-challenge[aria-pressed="true"] { color: var(--accent-2); overflow: hidden; text-overflow: ellipsis; max-width: 220px; }

/* --- Edytor --- */

.editor {
  position: relative;
  flex: 1;
  display: flex;
  min-height: 160px;
  background: var(--code-bg);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  font-family: var(--font-code);
  font-size: var(--code-size);
  line-height: var(--code-lh);
  font-variant-ligatures: none;
  font-feature-settings: "liga" 0, "calt" 0;
  box-shadow: var(--shadow);
}
.editor:focus-within { border-color: var(--focus); box-shadow: 0 0 0 3px color-mix(in srgb, var(--focus) 30%, transparent); }

/* --- Sterowanie --- */

.controls {
  display: flex; align-items: center; justify-content: space-between;
  gap: 10px 16px; flex-wrap: wrap;
}
.control-buttons { display: flex; gap: 6px; flex-wrap: wrap; }
.speed { display: flex; align-items: center; gap: 10px; font-size: 14px; font-weight: 600; }
.speed input { width: 130px; accent-color: var(--accent); }
.speed-out { min-width: 7.5em; color: var(--muted); font-weight: 500; font-size: 13px; }

/* --- Rysunek --- */

.stage {
  position: relative;
  flex: 1;
  min-height: 240px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  background: var(--stage-bg);
  box-shadow: var(--shadow);
}
.stage-view { position: absolute; inset: 0; }
.stage-canvas { display: block; width: 100%; height: 100%; touch-action: none; cursor: grab; }
.stage-canvas:active { cursor: grabbing; }
.stage-canvas:focus-visible { outline: 3px solid var(--focus); outline-offset: -3px; border-radius: var(--radius); }

.view-tools {
  position: absolute; top: 10px; right: 10px; z-index: 3;
  display: flex; flex-direction: column; gap: 4px;
  padding: 4px;
  background: color-mix(in srgb, var(--surface) 90%, transparent);
  border: 1px solid var(--border);
  border-radius: 10px;
  box-shadow: var(--shadow);
}
.view-tools .btn { min-height: 34px; width: 34px; border-color: transparent; background: transparent; }
.view-tools .btn:hover { background: var(--surface-3); }
.view-tools .btn[aria-pressed="true"] { color: var(--accent-2); }
.view-tools .btn[aria-pressed="false"] { color: var(--muted); }

.stage-scale {
  position: absolute; left: 12px; bottom: 8px;
  font: 500 12px/1 var(--font-ui);
  color: var(--stage-text);
  pointer-events: none;
}
.run-state {
  position: absolute; right: 10px; bottom: 10px; z-index: 2;
  font: 700 12px/1 var(--font-ui);
  padding: 5px 9px;
  border-radius: 999px;
  pointer-events: none;
}
.run-state:empty { display: none; }
.run-state[data-state="running"] { background: var(--accent-soft); color: var(--accent); }
.run-state[data-state="paused"] { background: var(--warn-bg); color: var(--warn); }

.stage-notice {
  position: absolute; left: 12px; right: 62px; top: 12px; z-index: 2;
  display: flex; gap: 8px; align-items: flex-start;
  padding: 10px 12px;
  border-radius: var(--radius-s);
  background: var(--warn-bg); color: var(--text);
  font-size: 13.5px;
  box-shadow: var(--shadow);
}
.stage-notice .icon { color: var(--warn); }
.stage-loading {
  position: absolute; inset: 0; z-index: 2;
  display: grid; place-items: center;
  color: var(--muted); font-weight: 600;
}

.status-line {
  display: flex; align-items: center; gap: 8px;
  min-height: 20px;
  font: 500 12.5px/1.4 var(--font-ui);
  color: var(--muted);
.toast.leaving { opacity: 0; transition: opacity .2s; }
.toast-text { flex: 1; }
@keyframes toast-in { from { opacity: 0; transform: translateY(8px); } }

/* --- Telefon i tablet --- */

@media (max-width: 960px) {
  .studio {
    display: flex; flex-direction: column;
    height: auto; min-height: 0;
