  addSegment(from: Vec3, to: Vec3, tok: Token): void {
    if (this.drawn.length - this.visibleFrom >= LIMITS.segments) {
      throw LogoFailure.at(tok, `Przekroczono limit ${big(LIMITS.segments)} odcinków na rysunku.`);
    }
    this.drawn.push({
